package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for {@link TypeFactory#constructType(Type, Class)}.
 */
public class TypeFactory_constructType_TriageGen0Test {

    @Test
    public void testConstructType_WithSimpleClass() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Type type = String.class;
        Class<?> contextClass = Integer.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithParameterizedType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Represents List<String>
        ParameterizedType parameterizedType = new ParameterizedTypeImpl(
                List.class, 
                new Type[]{String.class}, 
                new Type[]{String.class});

        Class<?> contextClass = Map.class;

        JavaType result = typeFactory.constructType(parameterizedType, contextClass);

        assertNotNull(result);
        assertEquals(List.class, result.getRawClass());
        assertEquals(1, result.getTypeParameters().length);
        assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructType_WithContextClassProvidingTypeInformation() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Type is a wildcard/variable that should resolve via context
        // In this case, we use a TypeReference-like structure or a simple Type variable
        // But for the sake of testing the specific signature:
        // constructType(Type type, Class<?> contextClass) calls constructType(type, constructType(contextClass))

        Type type = List.class;
        Class<?> contextClass = Map.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        assertNotNull(result);
        assertEquals(List.class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithNullType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Depending on Jackson version behavior, null might return unknownType or throw NPE.
        // Given the implementation: constructType(type, constructType(contextClass))
        // If type is null, constructType(null) is usually called.

        JavaType result = typeFactory.constructType(null, Object.class);

        // Jackson's constructType(null) typically returns unknownType()
        assertEquals(TypeFactory.unknownType(), result);
    }

    @Test
    public void testConstructType_WithNullContext() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // If contextClass is null, constructType(null) is called for the second argument.
        // This tests the delegation chain.
        JavaType result = typeFactory.constructType(String.class, null);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructType_WithArrayType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Type arrayType = String[].class;
        Class<?> contextClass = Object.class;

        JavaType result = typeFactory.constructType(arrayType, contextClass);

        assertNotNull(result);
        assertEquals(String[].class, result.getRawClass());
    }

    /**
     * Helper class to simulate ParameterizedType for testing purposes
     */
    private static class ParameterizedTypeImpl implements ParameterizedType {
        private final Class<?> rawType;
        private final Type[] actualTypeArguments;
        private final Type[] formalTypeArguments;

        public ParameterizedTypeImpl(Class<?> rawType, Type[] actualTypeArguments, Type[] formalTypeArguments) {
            this.rawType = rawType;
            this.actualTypeArguments = actualTypeArguments;
            this.formalTypeArguments = formalTypeArguments;
        }

        @Override
        public Type[] getActualTypeArguments() { return actualTypeArguments; }

        @Override
        public Type[] getFormalTypeArguments() { return formalTypeArguments; }

        @Override
        public Class<?> getRawType() { return rawType; }
    }
}
